/*-----------------------------------------------------------------------------
 * Umicom Framework — Native Language Model Laboratory
 * File: learning/native-llm/generate_text.c
 *
 * PURPOSE:
 *   Read an explicitly approved native decoder checkpoint and generate raw
 *   bytes from a prompt. All sampling, tokenisation and inference live in
 *   the shared Framework; this application handles only arguments and output.
 *
 * SAFETY:
 *   Only open trusted checkpoints. The checksum detects accidental damage,
 *   not hostile modification. Display generated bytes in an escaped form to
 *   avoid arbitrary control characters affecting the terminal. Model output
 *   is untrusted text; this tool never executes generated commands or code.
 *
 * AUTHOR AND ORGANISATION:
 *   Sammy Hegab
 *   Umicom Foundation
 * LICENCE: MIT
 *---------------------------------------------------------------------------*/
#include "umicom/ai/training/generation.h"
#include "umicom/ai/training/checkpoint.h"

#include <errno.h>
#include <limits.h>
#include <inttypes.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int ParseSize(const char *text, size_t maximum, size_t *outValue)
{
    char *end = NULL;
    unsigned long long value;
    if (text == NULL || text[0] == '\0' || text[0] == '-' ||
        outValue == NULL) return 0;
    errno = 0;
    value = strtoull(text, &end, 10);
    if (errno != 0 || end == text || *end != '\0' ||
        value == 0ULL || value > (unsigned long long)maximum)
        return 0;
    *outValue = (size_t)value;
    return 1;
}

static int ParseSeed(const char *text, uint64_t *outValue)
{
    char *end = NULL;
    unsigned long long value;
    if (text == NULL || text[0] == '\0' || text[0] == '-' ||
        outValue == NULL) return 0;
    errno = 0;
    value = strtoull(text, &end, 10);
    if (errno != 0 || end == text || *end != '\0') return 0;
#if ULLONG_MAX > UINT64_MAX
    if (value > UINT64_MAX) return 0;
#endif
    *outValue = (uint64_t)value;
    return 1;
}

static int ParseTemperature(const char *text, float *outValue)
{
    char *end = NULL;
    float parsed;
    if (text == NULL || text[0] == '\0' || outValue == NULL)
        return 0;
    errno = 0;
    parsed = strtof(text, &end);
    if (errno != 0 || end == text || *end != '\0' ||
        !isfinite(parsed) || parsed <= 0.0F) return 0;
    *outValue = parsed;
    return 1;
}

static void WriteEscaped(const uint8_t *bytes, size_t length)
{
    for (size_t index = 0U; index < length; ++index) {
        unsigned char value = bytes[index];
        if (value == '\n') fputs("\\n", stdout);
        else if (value == '\r') fputs("\\r", stdout);
        else if (value == '\t') fputs("\\t", stdout);
        else if (value == '\\') fputs("\\\\", stdout);
        else if (value >= 0x20U && value <= 0x7EU)
            putchar((int)value);
        else printf("\\x%02X", (unsigned)value);
    }
    putchar('\n');
}

int main(int argc, char **argv)
{
    UmiAiTrainingDecoder *model = NULL;
    UmiAiTrainingDecoderConfig config;
    UmiAiTrainingSamplingOptions options = {1.0F, 1U};
    uint64_t completedSteps = 0U;
    uint64_t seed = UINT64_C(20261021);
    size_t requested = 48U, produced = 0U;
    uint8_t generated[UMI_AI_GENERATION_MAX_NEW_TOKENS];
    UmiStatus status;
    if (argc < 3 || argc > 7) {
        fprintf(stderr,
            "usage: umicom-native-llm-generate <trusted-checkpoint> <prompt> "
            "[count 1..256] [top_k] [temperature] [seed]\n");
        return 2;
    }
    if ((argc >= 4 && !ParseSize(argv[3],
                                  UMI_AI_GENERATION_MAX_NEW_TOKENS, &requested)) ||
        (argc >= 5 && !ParseSize(argv[4],
                                  UMI_AI_DECODER_MAX_VOCABULARY, &options.topK)) ||
        (argc >= 6 && !ParseTemperature(argv[5], &options.temperature)) ||
        (argc >= 7 && !ParseSeed(argv[6], &seed))) {
        fputs("invalid count, top_k, temperature or seed\n", stderr);
        return 2;
    }
    size_t promptLength = strlen(argv[2]);
    if (promptLength > UMI_AI_GENERATION_MAX_PROMPT_TOKENS) {
        fputs("prompt byte count exceeds the native generation limit\n", stderr);
        return 2;
    }
    status = UmiAiTrainingDecoderCheckpointLoadFile(argv[1], &model);
    if (status != UMI_STATUS_OK) {
        fprintf(stderr, "trusted checkpoint rejected (status=%d)\n",
                (int)status);
        return 1;
    }
    status = UmiAiTrainingDecoderInspect(model, &config, &completedSteps);
    if (status == UMI_STATUS_OK) {
        status = UmiAiTrainingDecoderGenerateBytes(model,
            (const uint8_t *)(const void *)argv[2], promptLength,
            &options, requested, seed, generated, sizeof(generated), &produced);
    }
    if (status != UMI_STATUS_OK) {
        fprintf(stderr, "generation rejected (status=%d)\n", (int)status);
        UmiAiTrainingDecoderDestroy(model);
        return 1;
    }
    printf("Native decoder: vocabulary=%u, context=%u, trained steps=%" PRIu64
           ", requested=%zu, top_k=%zu, temperature=%.4f, seed=%" PRIu64 "\n",
           (unsigned)config.vocabularySize, (unsigned)config.contextLength,
           completedSteps, requested, options.topK,
           (double)options.temperature, seed);
    printf("Generated %zu raw bytes (escaped):\n", produced);
    WriteEscaped(generated, produced);
    puts("Small educational model: generated text may be meaningless or invalid UTF-8.");
    UmiAiTrainingDecoderDestroy(model);
    return 0;
}
